#!/usr/bin/env python3
"""longer_holds_study.py -- LONGER HOLDS study (WIP, 2026-09-27). Read-only on the desk; all data/outputs in /tmp/lh.
Daily-horizon edges (12-1 momentum, 1-week reversal, gap/PEAD drift, overnight, daily gap-and-go) on free Alpaca SIP
daily bars 2016-01..2026-09 incl. inactive assets, costs from a quote-calibrated spread model (AR/CS failed the cross-check).
Findings: docs/studies/LONGER_HOLDS_2026-09-27.md.

The study is seven small modules bundled here. `unpack` writes them to /tmp/lh, then run the phases there:
  cd ~/repo/trading-helper && .venv/bin/python tools/studies/longer_holds_study.py unpack
  cd /tmp/lh && export PYTHONPATH=/tmp/lh:/tmp:$HOME/repo/trading-helper:$HOME/repo/trading-helper/tools
  nice -n 15 ~/repo/trading-helper/.venv/bin/python lh_fetch.py all rawM   # daily adj bars + monthly raw (price filter)
  nice -n 15 ~/repo/trading-helper/.venv/bin/python lh_panel.py            # -> panel.npz
  nice -n 15 ~/repo/trading-helper/.venv/bin/python lh_run.py cands        # news_cands.json + quote_sample.json
  nice -n 15 ~/repo/trading-helper/.venv/bin/python lh_quotes.py           # real SIP NBBO sample -> quotes.json
  nice -n 15 ~/repo/trading-helper/.venv/bin/python lh_news.py             # Benzinga news flags -> news.json (resumable)
  nice -n 15 ~/repo/trading-helper/.venv/bin/python lh_run.py analyze      # -> LONGER_HOLDS_raw.txt, results.json
All phases resume from their caches.
"""
import os, sys
MODULES = {'lh_fetch': '"""fetch phase: assets + daily SIP bars (adjustment=all and raw) 2016-01-01..2026-09-25 -> /tmp/lh/bars_{adj}.pkl"""\nimport json, os, pickle, re, sys, time\nimport numpy as np, requests\nfrom config import load_config\nfrom ticker_filters import is_common, is_levered_etp\nOUT = "/tmp/lh"\nc = load_config() or {}\nH = {"APCA-API-KEY-ID": c.get("api_key"), "APCA-API-SECRET-KEY": c.get("secret_key")}\nFUNDISH = re.compile(r"\\b(ETF|ETN|FUND|ISHARES|SPDR|PROSHARES|DIREXION|INVESCO|VANGUARD|INDEX|PORTFOLIO|TREASURY|BOND|MUNICIPAL|"\n                     r"LEVERAGED|INVERSE|2X|3X|BULL|BEAR|WARRANTS?|RIGHTS?|UNITS?|PREFERRED|DEPOSITARY SHARES? REPR|NOTES?|DEBENTURES?|"\n                     r"ACQUISITION CORP|ACQUISITION CO|SPAC|CAPITAL TRUST|TRUST UNITS?|ROYALTY TRUST|CLOSED.END|MUTUAL)\\b", re.I)\n\n\ndef assets():\n    p = f"{OUT}/universe_assets.json"\n    if os.path.exists(p):\n        return json.load(open(p))\n    raw = json.load(open(f"{OUT}/assets_raw.json"))\n    ok_ex = {"NYSE", "NASDAQ", "AMEX"}   # ARCA/BATS listings are overwhelmingly ETPs -> excluded\n    act = {x["symbol"] for x in raw["active"]}\n    keep = {}\n    for st in ("active", "inactive"):\n        for a in raw[st]:\n            s, nm = a["symbol"], a.get("name") or ""\n            if a["exchange"] not in ok_ex or not is_common(s) or is_levered_etp(s, nm) or FUNDISH.search(nm):\n                continue\n            if st == "inactive" and s in act:\n                continue  # reused ticker: the active symbol\'s history wins\n            keep[s] = {"status": st, "name": nm, "exchange": a["exchange"]}\n    json.dump(keep, open(p, "w"))\n    return keep\n\n\ndef fetch(adj):\n    p = f"{OUT}/bars_{adj}.pkl"\n    tf = "1Month" if adj == "rawM" else "1Day"\n    adj_q = "raw" if adj == "rawM" else adj\n    D = pickle.load(open(p, "rb")) if os.path.exists(p) else {}\n    syms = sorted(set(assets()) | {"SPY"})\n    todo = [s for s in syms if s not in D]\n    print(adj, "todo", len(todo), "have", len(D), flush=True)\n    t0 = time.time()\n    B = 500 if adj == "rawM" else 100\n    for i in range(0, len(todo), B):\n        b = todo[i:i + B]\n        acc = {s: [] for s in b}\n        tok = None\n        while True:\n            prm = {"symbols": ",".join(b), "timeframe": tf, "start": "2016-01-01", "end": "2026-09-26",\n                   "limit": 10000, "feed": "sip", "adjustment": adj_q}\n            if tok:\n                prm["page_token"] = tok\n            k = 0\n            while k < 6:\n                try:\n                    r = requests.get("https://data.alpaca.markets/v2/stocks/bars", params=prm, headers=H, timeout=90)\n                    if r.status_code == 429:\n                        time.sleep(3); continue   # shared key is rate-limited: wait, do not count as a failure\n                    r.raise_for_status(); j = r.json(); break\n                except Exception as e:  # noqa: BLE001\n                    print("err", type(e).__name__, str(e)[:80], flush=True); k += 1; time.sleep(5 * k)\n            else:\n                raise SystemExit("fetch failed")\n            for s, rows in (j.get("bars") or {}).items():\n                acc.setdefault(s, []).extend(rows)\n            tok = j.get("next_page_token")\n            time.sleep(0.32)\n            if not tok:\n                break\n        for s, rows in acc.items():\n            if not rows:\n                D[s] = None; continue\n            D[s] = {"d": np.array([r["t"][:10] for r in rows], dtype="datetime64[D]"),\n                    "o": np.array([r["o"] for r in rows], float), "h": np.array([r["h"] for r in rows], float),\n                    "l": np.array([r["l"] for r in rows], float), "c": np.array([r["c"] for r in rows], float),\n                    "v": np.array([r["v"] for r in rows], float)}\n        if (i // B) % max(1000 // B, 1) == 0:\n            pickle.dump(D, open(p, "wb"))\n            print(adj, i + len(b), "/", len(todo), f"{time.time() - t0:.0f}s", flush=True)\n    pickle.dump(D, open(p, "wb"))\n    print(adj, "done", len(D), sum(v is not None for v in D.values()), flush=True)\n\n\nif __name__ == "__main__":\n    a = assets()\n    import collections\n    print("assets", len(a), collections.Counter(v["status"] for v in a.values()), flush=True)\n    for adj in sys.argv[1:] or ["all", "raw"]:\n        fetch(adj)\n', 'lh_news': '"""news phase: Alpaca (Benzinga) news for candidate event name-days -> /tmp/lh/news.json\nwindow per event day t: [prev session 16:00 ET, t 16:00 ET]. Earnings flag: headline matches EARN and the article tags <=3 symbols."""\nimport json, os, re, sys, time, collections\nfrom datetime import datetime, timedelta\nfrom zoneinfo import ZoneInfo\nimport requests\nfrom config import load_config\nET = ZoneInfo("America/New_York")\nOUT = "/tmp/lh"\nEARN = re.compile(r"\\b(earnings|EPS|Q[1-4]\\b|quarter(ly)?|fiscal|results|revenue|sales|guidance|outlook|beats?|miss(es)?|tops|reports?)\\b", re.I)\nc = load_config() or {}\nH = {"APCA-API-KEY-ID": c.get("api_key"), "APCA-API-SECRET-KEY": c.get("secret_key")}\n\n\ndef main():\n    cands = json.load(open(f"{OUT}/news_cands.json"))     # {day: {"prev": prevday, "syms": [...]}}\n    p = f"{OUT}/news.json"\n    got = json.load(open(p)) if os.path.exists(p) else {}\n    days = [d for d in sorted(cands) if d not in got]\n    print("days todo", len(days), flush=True)\n    t0 = time.time()\n    for n, d in enumerate(days):\n        x = cands[d]\n        st = datetime.strptime(x["prev"], "%Y-%m-%d").replace(hour=16, tzinfo=ET)\n        en = datetime.strptime(d, "%Y-%m-%d").replace(hour=16, tzinfo=ET)\n        rec = collections.defaultdict(lambda: {"n": 0, "earn": 0, "h": []})\n        syms = x["syms"]\n        for i in range(0, len(syms), 40):\n            b = set(syms[i:i + 40]); tok = None\n            while True:\n                prm = {"symbols": ",".join(sorted(b)), "start": st.isoformat(), "end": en.isoformat(), "limit": 50,\n                       "include_content": "false", "sort": "asc"}\n                if tok:\n                    prm["page_token"] = tok\n                for k in range(6):\n                    try:\n                        r = requests.get("https://data.alpaca.markets/v1beta1/news", params=prm, headers=H, timeout=60)\n                        if r.status_code == 429:\n                            time.sleep(10); continue\n                        r.raise_for_status(); j = r.json(); break\n                    except Exception as e:  # noqa: BLE001\n                        print("err", type(e).__name__, str(e)[:80], flush=True); time.sleep(5 * (k + 1))\n                else:\n                    raise SystemExit("news fetch failed")\n                for a in j.get("news", []):\n                    ss = a.get("symbols") or []\n                    hl = a.get("headline") or ""\n                    for s in ss:\n                        if s in b:\n                            q = rec[s]; q["n"] += 1\n                            if len(ss) <= 3 and EARN.search(hl):\n                                q["earn"] += 1\n                            if len(q["h"]) < 3:\n                                q["h"].append(hl[:120])\n                tok = j.get("next_page_token")\n                time.sleep(0.3)\n                if not tok:\n                    break\n        got[d] = dict(rec)\n        if n % 50 == 0:\n            json.dump(got, open(p, "w"))\n            print(n, "/", len(days), d, f"{time.time() - t0:.0f}s", flush=True)\n    json.dump(got, open(p, "w"))\n    print("done", len(got), flush=True)\n\n\nif __name__ == "__main__":\n    main()\n', 'lh_quotes': '"""quotes phase: real SIP NBBO spreads on a sample of name-days -> /tmp/lh/quotes.json\nsample from quote_sample.json {day: [syms]}; times 09:35, 12:30, 15:55 ET; 3-second window; median (ask-bid)/mid per window."""\nimport json, os, time, statistics\nfrom datetime import datetime, timedelta\nfrom zoneinfo import ZoneInfo\nimport requests\nfrom config import load_config\nET = ZoneInfo("America/New_York")\nOUT = "/tmp/lh"\nTIMES = ((9, 35), (12, 30), (15, 55))\nc = load_config() or {}\nH = {"APCA-API-KEY-ID": c.get("api_key"), "APCA-API-SECRET-KEY": c.get("secret_key")}\n\n\ndef main():\n    smp = json.load(open(f"{OUT}/quote_sample.json"))\n    p = f"{OUT}/quotes.json"\n    got = json.load(open(p)) if os.path.exists(p) else {}\n    for d, syms in sorted(smp.items()):\n        for hh, mm in TIMES:\n            key = f"{d} {hh:02d}:{mm:02d}"\n            if key in got:\n                continue\n            st = datetime.strptime(d, "%Y-%m-%d").replace(hour=hh, minute=mm, tzinfo=ET)\n            acc = {}\n            tok = None\n            while True:\n                prm = {"symbols": ",".join(syms), "start": st.isoformat(), "end": (st + timedelta(seconds=3)).isoformat(),\n                       "limit": 10000, "feed": "sip"}\n                if tok:\n                    prm["page_token"] = tok\n                for k in range(5):\n                    try:\n                        r = requests.get("https://data.alpaca.markets/v2/stocks/quotes", params=prm, headers=H, timeout=60)\n                        if r.status_code == 429:\n                            time.sleep(10); continue\n                        r.raise_for_status(); j = r.json(); break\n                    except Exception as e:  # noqa: BLE001\n                        print("err", type(e).__name__, str(e)[:80], flush=True); time.sleep(5)\n                else:\n                    j = {}\n                for s, qs in (j.get("quotes") or {}).items():\n                    for q in qs:\n                        b, a = q.get("bp") or 0, q.get("ap") or 0\n                        if b > 0 and a > b:\n                            acc.setdefault(s, []).append((a - b) / ((a + b) / 2))\n                tok = j.get("next_page_token")\n                time.sleep(0.3)\n                if not tok:\n                    break\n            got[key] = {s: statistics.median(v) for s, v in acc.items()}\n        json.dump(got, open(p, "w"))\n        print(d, len(syms), flush=True)\n    print("done", flush=True)\n\n\nif __name__ == "__main__":\n    main()\n', 'lh_panel': '"""panel phase: T x N matrices from bars_all / bars_raw + spread estimators -> /tmp/lh/panel.npz"""\nimport json, pickle, sys\nimport numpy as np\nOUT = "/tmp/lh"\n\n\ndef build():\n    A = pickle.load(open(f"{OUT}/bars_all.pkl", "rb"))\n    R = pickle.load(open(f"{OUT}/bars_rawM.pkl", "rb"))   # monthly RAW bars: raw/adjusted factor per symbol-month\n    assets = json.load(open(f"{OUT}/universe_assets.json"))\n    dates = A["SPY"]["d"]\n    T = len(dates)\n    syms = sorted(s for s, v in A.items() if v is not None and s != "SPY" and len(v["d"]) >= 30)\n    # renamed-ticker dedupe: drop an inactive series whose bars duplicate an active series (same date, close, volume)\n    act = [s for s in syms if assets.get(s, {}).get("status") == "active"]\n    ina = [s for s in syms if assets.get(s, {}).get("status") == "inactive"]\n    probe = {}\n    for s in ina:\n        v = A[s]; k = len(v["d"]) // 2\n        probe.setdefault(v["d"][k], []).append((s, round(v["c"][k], 4), v["v"][k]))\n    dup = set()\n    for s in act:\n        v = A[s]\n        idx = np.searchsorted(v["d"], np.array(list(probe.keys()), dtype="datetime64[D]"))\n        for dd, i in zip(probe.keys(), idx):\n            if i < len(v["d"]) and v["d"][i] == dd:\n                for (si, ci, vi) in probe[dd]:\n                    if abs(round(v["c"][i], 4) - ci) < 1e-6 and v["v"][i] == vi:\n                        dup.add(si)\n    syms = [s for s in syms if s not in dup]\n    N = len(syms)\n    print("T", T, "N", N, "dropped dup inactive", len(dup), sorted(dup)[:20], flush=True)\n    M = {k: np.full((T, N), np.nan, dtype=np.float64) for k in ("o", "h", "l", "c", "v", "rc", "ro")}\n    for j, s in enumerate(syms):\n        v = A[s]\n        ii = np.searchsorted(dates, v["d"]); ok = (ii < T) & (dates[np.minimum(ii, T - 1)] == v["d"]); ok0 = ok\n        for k in ("o", "h", "l", "c", "v"):\n            M[k][ii[ok], j] = v[k][ok]\n        r = R.get(s)\n        if r is not None:\n            # factor(month) = raw monthly close / adjusted close of that month\'s last daily bar; raw daily ~= adj daily * factor\n            mon = v["d"].astype("datetime64[M]")\n            last = np.r_[mon[1:] != mon[:-1], True]\n            fac_m = {}\n            rm = dict(zip(r["d"].astype("datetime64[M]"), r["c"]))\n            for mm, cc in zip(mon[last], v["c"][last]):\n                if mm in rm and cc > 0:\n                    fac_m[mm] = rm[mm] / cc\n            fac = np.array([fac_m.get(mm, np.nan) for mm in mon])\n            M["rc"][ii[ok0], j] = (v["c"] * fac)[ok0]; M["ro"][ii[ok0], j] = (v["o"] * fac)[ok0]\n    spy = A["SPY"]\n    np.savez(f"{OUT}/panel.npz", dates=dates.astype(str), syms=np.array(syms),\n             status=np.array([assets.get(s, {}).get("status", "?") for s in syms]),\n             spy_o=spy["o"], spy_h=spy["h"], spy_l=spy["l"], spy_c=spy["c"], spy_v=spy["v"], **M)\n    print("saved", flush=True)\n\n\nif __name__ == "__main__":\n    build()\n', 'lh_core': '"""shared: load panel, derived fields, spread estimators, metrics"""\nimport numpy as np, pandas as pd\nOUT = "/tmp/lh"\nIS_END = "2021-12-31"\n\n\ndef load():\n    z = np.load(f"{OUT}/panel.npz", allow_pickle=False)\n    P = {k: z[k] for k in z.files}\n    P["dates"] = pd.to_datetime(P["dates"])\n    c, o, h, l, v, rc = P["c"], P["o"], P["h"], P["l"], P["v"], P["rc"]\n    T, N = c.shape\n    dv = c * v\n    P["adv20"] = pd.DataFrame(dv).rolling(20, min_periods=15).mean().values\n    P["vavg20_prev"] = pd.DataFrame(v).rolling(20, min_periods=15).mean().shift(1).values\n    P["elig"] = (rc >= 5) & (P["adv20"] >= 5e6) & np.isfinite(c)\n    P["liquid"] = P["elig"] & (P["adv20"] >= 5e7)\n    P["band"] = P["elig"] & (rc >= 20) & (rc <= 100)\n    P["cf"] = pd.DataFrame(c).ffill(limit=None).values\n    # --- Abdi-Ranaldo (2017) close-high-low estimator, 2-day version, 21d mean, value at t uses data through t\n    lc, eta = np.log(c), (np.log(h) + np.log(l)) / 2\n    prod = np.full_like(c, np.nan)\n    prod[1:] = (lc[:-1] - eta[:-1]) * (lc[:-1] - eta[1:])          # stamped at t (needs eta_t)\n    m = pd.DataFrame(prod).rolling(21, min_periods=10).mean().values\n    ar = np.sqrt(np.maximum(4 * m, 0))\n    # --- Corwin-Schultz (2012) with overnight adjustment, 21d mean of 2-day estimates (negatives -> 0)\n    h2, l2 = h.copy(), l.copy()\n    cp = np.vstack([np.full((1, N), np.nan), c[:-1]])\n    up = l2 > cp; dn = h2 < cp\n    adj = np.where(up, l2 - cp, np.where(dn, h2 - cp, 0.0))\n    adj = np.nan_to_num(adj)\n    h2 = h2 - adj; l2 = l2 - adj\n    with np.errstate(all="ignore"):\n        b = np.full_like(c, np.nan); g = np.full_like(c, np.nan)\n        b[1:] = np.log(h2[:-1] / l2[:-1]) ** 2 + np.log(h2[1:] / l2[1:]) ** 2\n        g[1:] = np.log(np.maximum(h2[:-1], h2[1:]) / np.minimum(l2[:-1], l2[1:])) ** 2\n        k = 3 - 2 * np.sqrt(2)\n        a = (np.sqrt(2 * b) - np.sqrt(b)) / k - np.sqrt(g / k)\n        s = 2 * (np.exp(a) - 1) / (1 + np.exp(a))\n    s = np.where(np.isfinite(s), np.maximum(s, 0), np.nan)\n    cs = pd.DataFrame(s).rolling(21, min_periods=10).mean().values\n    tick = 0.01 / rc\n    P["spr_ar"], P["spr_cs"], P["tick"] = ar, cs, tick\n    P["spr_arm"] = np.where(np.isfinite(ar), np.clip(np.fmax(ar, tick), 0, 0.05), 0.01)   # AR model (sensitivity only)\n    quote_model(P)\n    return P\n\n\ndef quote_model(P):\n    """Primary cost model, calibrated on real SIP NBBO samples (quotes.json, 2025-26): log(quoted spread at a time of day)\n    ~ a + b log(ADV20) + c log(price), fitted separately for 09:35 (open trades) and 15:55 (close trades); mean = exp(fit + sd^2/2).\n    Row t uses ADV/price of t-1 (known before trading). Clipped to [1 tick, 5%]."""\n    import json\n    q = json.load(open(f"{OUT}/quotes.json"))\n    col = {s: j for j, s in enumerate(P["syms"])}; dix = {str(x.date()): i for i, x in enumerate(P["dates"])}\n    lad = np.log(np.vstack([np.full((1, P["c"].shape[1]), np.nan), P["adv20"][:-1]]))\n    lpx = np.log(np.vstack([np.full((1, P["c"].shape[1]), np.nan), P["rc"][:-1]]))\n    P["qfit"] = {}\n    for hm, key in (("09:35", "spr_o"), ("15:55", "spr")):\n        X, y = [], []\n        for k, m in q.items():\n            d, h = k.split()\n            if h != hm:\n                continue\n            t = dix[d]\n            for s, sp in m.items():\n                j = col.get(s)\n                if j is None or not (np.isfinite(lad[t, j]) and np.isfinite(lpx[t, j])):\n                    continue\n                X.append([1, lad[t, j], lpx[t, j]]); y.append(np.log(max(sp, 1e-5)))\n        X, y = np.array(X), np.array(y)\n        b, *_ = np.linalg.lstsq(X, y, rcond=None)\n        sd = float(np.std(y - X @ b))\n        with np.errstate(all="ignore"):\n            est = np.exp(b[0] + b[1] * lad + b[2] * lpx + sd * sd / 2)\n        tick = 0.01 / np.exp(lpx)\n        P[key] = np.where(np.isfinite(est), np.clip(np.fmax(est, tick), 0, 0.05), 0.01)\n        P["qfit"][hm] = dict(n=len(y), coef=[float(x) for x in b], sd=sd)\n    return P\n\n\nSTART = 252   # strategies need 12 months of history: evaluation window starts 2017-01\n\n\ndef metrics(ret, dates, spy_ret, label="", start=START):\n    """ret, spy_ret: daily simple returns aligned on dates; evaluated from index `start` (2017-01) on."""\n    r = pd.Series(ret[start:], index=dates[start:]).fillna(0.0)\n    s = pd.Series(spy_ret[start:], index=dates[start:]).fillna(0.0)\n    out = {}\n    for nm, msk in (("ALL", slice(None)), ("IS", r.index <= IS_END), ("OOS", r.index > IS_END)):\n        rr, ss = r[msk], s[msk]\n        if len(rr) < 20:\n            continue\n        eq = (1 + rr).cumprod()\n        yrs = len(rr) / 252\n        cagr = eq.iloc[-1] ** (1 / yrs) - 1\n        vol = rr.std() * np.sqrt(252)\n        sh = rr.mean() / rr.std() * np.sqrt(252) if rr.std() > 0 else np.nan\n        mdd = (eq / eq.cummax() - 1).min()\n        cov = np.cov(rr, ss)\n        beta = cov[0, 1] / cov[1, 1]\n        alpha = (rr.mean() - beta * ss.mean()) * 252\n        resid = rr - beta * ss\n        t_a = (resid.mean() / resid.std() * np.sqrt(len(resid))) if resid.std() > 0 else np.nan\n        seq = (1 + ss).cumprod()\n        out[nm] = dict(cagr=cagr, vol=vol, sharpe=sh, mdd=mdd, corr=np.corrcoef(rr, ss)[0, 1], beta=beta,\n                       alpha=alpha, alpha_t=t_a, spy_cagr=seq.iloc[-1] ** (1 / yrs) - 1,\n                       spy_sharpe=ss.mean() / ss.std() * np.sqrt(252))\n    yr = r.groupby(r.index.year).apply(lambda x: (1 + x).prod() - 1)\n    sy = s.groupby(s.index.year).apply(lambda x: (1 + x).prod() - 1)\n    out["years"] = {int(y): (float(yr[y]), float(sy[y])) for y in yr.index}\n    return out\n\n\ndef fmt_m(m, keys=("ALL", "IS", "OOS")):\n    rows = []\n    for k in keys:\n        if k not in m:\n            continue\n        x = m[k]\n        rows.append(f"{k:>3} CAGR {x[\'cagr\']*100:6.1f}% (SPY {x[\'spy_cagr\']*100:5.1f}%)  Sharpe {x[\'sharpe\']:5.2f} (SPY {x[\'spy_sharpe\']:4.2f})"\n                    f"  MDD {x[\'mdd\']*100:6.1f}%  corr {x[\'corr\']:4.2f}  beta {x[\'beta\']:4.2f}  alpha {x[\'alpha\']*100:6.1f}%/yr (t {x[\'alpha_t\']:4.1f})")\n    return "\\n".join(rows)\n\n\ndef fmt_years(m):\n    return "  ".join(f"{y}:{a*100:+.0f}({b*100:+.0f})" for y, (a, b) in m["years"].items())\n', 'lh_strat': '"""strategy engines: rebalanced portfolios, overnight, event slot-portfolio, per-trade stats"""\nimport numpy as np, pandas as pd\n\n\ndef returns(P):\n    c, o, cf = P["c"], P["o"], P["cf"]\n    T, N = c.shape\n    R = np.zeros_like(c); R[1:] = cf[1:] / cf[:-1] - 1\n    R = np.nan_to_num(R, nan=0.0, posinf=0.0, neginf=0.0)\n    ON = np.full_like(c, np.nan); ON[1:] = o[1:] / c[:-1] - 1         # close t-1 -> open t (needs both real)\n    ID = c / o - 1\n    P["R"], P["ON"], P["ID"] = R, ON, ID\n    spy = P["spy_c"]; P["spy_r"] = np.r_[0, spy[1:] / spy[:-1] - 1]\n    P["spy_on"] = np.r_[0, P["spy_o"][1:] / spy[:-1] - 1]\n    return P\n\n\ndef rebal_portfolio(P, rebal_idx, picks, mode="close", cost_mult=1.0, fixed_side=None):\n    """Equal-weight picks[k] (column idx array) chosen at close of day rebal_idx[k]; held to the next rebalance.\n    mode=close: trade at that close. mode=open: trade at the next open. Cost per traded $ = half spread (or fixed_side)."""\n    R, spr, o = P["R"], P["spr"], P["o"]\n    T, N = R.shape\n    ret = np.zeros(T); cost_s = np.zeros(T); turn = []\n    w = np.zeros(N); cash = 1.0\n    rset = dict(zip(rebal_idx, picks))\n\n    def trade(pk, tot, sp_row):\n        wn = np.zeros(N)\n        if len(pk):\n            wn[pk] = tot / len(pk)\n        dw = np.abs(wn - w)\n        side = fixed_side if fixed_side is not None else np.nan_to_num(sp_row, nan=0.01) / 2 * cost_mult\n        cst = float((dw * side).sum()) + (0 if len(pk) else 0.0)\n        turn.append(dw.sum() / tot / 2)\n        if len(pk):\n            return wn * (1 - cst / tot), 0.0, cst / tot\n        return wn, tot - cst, cst / tot\n\n    for d in range(rebal_idx[0], T):\n        tot0 = w.sum() + cash\n        if d > rebal_idx[0]:\n            if mode == "open" and (d - 1) in rset:\n                on = np.where(np.isfinite(P["ON"][d]), P["ON"][d], R[d])\n                w = w * (1 + on)\n                pk = rset[d - 1]; pk = pk[np.isfinite(o[d, pk]) & np.isfinite(P["c"][d, pk])]\n                w, cash, cs = trade(pk, w.sum() + cash, P["spr_o"][d])\n                cost_s[d] = cs\n                w = w * (1 + np.nan_to_num(P["ID"][d]))\n            else:\n                w = w * (1 + R[d])\n        if mode == "close" and d in rset:\n            w, cash, cs = trade(rset[d], w.sum() + cash, spr[d])\n            cost_s[d] = cs\n        ret[d] = (w.sum() + cash) / tot0 - 1\n    return ret, cost_s, turn\n\n\ndef event_trades(P, events, H, entry="close", dedupe=True):\n    """events: list of (t, j, score). Returns per-trade gross/net and SPY-relative over same window."""\n    c, o, spr, cf = P["c"], P["o"], P["spr"], P["cf"]\n    spyc, spyo = P["spy_c"], P["spy_o"]\n    T = c.shape[0]\n    last = {}\n    rows = []\n    for t, j, sc in sorted(events):\n        if dedupe and j in last and t - last[j] < H:\n            continue\n        te = t + 1 if entry == "open" else t\n        tx = t + H\n        if tx >= T or te >= T:\n            continue\n        pin = o[te, j] if entry == "open" else c[t, j]\n        pout = cf[tx, j]\n        if not (np.isfinite(pin) and np.isfinite(pout) and pin > 0):\n            continue\n        last[j] = t\n        g = pout / pin - 1\n        hs_in = (P["spr_o"][te, j] if entry == "open" else spr[t, j]) / 2; hs_out = spr[tx, j] / 2 if np.isfinite(c[tx, j]) else spr[t, j] / 2\n        net = (1 + g) * (1 - hs_in) * (1 - hs_out) - 1\n        sin = spyo[te] if entry == "open" else spyc[t]\n        rows.append((t, j, g, net, spyc[tx] / sin - 1, hs_in + hs_out))\n    return pd.DataFrame(rows, columns=["t", "j", "gross", "net", "spy", "cost"])\n\n\ndef trade_summary(df, dates, is_end="2021-12-31"):\n    if len(df) == 0:\n        return {"n": 0, "years": {}}\n    d = pd.to_datetime(dates[df.t.values])\n    out = {}\n    for nm, m in (("ALL", np.ones(len(df), bool)), ("IS", d <= is_end), ("OOS", d > is_end)):\n        x = df[m]\n        if len(x) < 5:\n            out[nm] = {"n": int(len(x))}; continue\n        ex = x.net - x.spy\n        out[nm] = dict(n=int(len(x)), gross=x.gross.mean(), net=x.net.mean(), med=x.net.median(), win=(x.net > 0).mean(),\n                       xs_spy=ex.mean(), t_xs=ex.mean() / ex.std() * np.sqrt(len(ex)) if ex.std() > 0 else np.nan,\n                       cost=x.cost.mean(), per_yr=len(x) / max((d[m].max() - d[m].min()).days / 365.25, 0.5))\n    out["years"] = {int(y): (int(len(g)), float(g.net.mean()), float((g.net - g.spy).mean()))\n                    for y, g in df.groupby(d.year)}\n    return out\n\n\ndef fmt_t(s):\n    rows = []\n    for k in ("ALL", "IS", "OOS"):\n        x = s.get(k)\n        if not x or "gross" not in x:\n            rows.append(f"{k:>3} n={x.get(\'n\', 0) if x else 0}"); continue\n        rows.append(f"{k:>3} n={x[\'n\']:5d} ({x[\'per_yr\']:.0f}/yr)  gross {x[\'gross\']*100:+6.2f}%  cost {x[\'cost\']*100:4.2f}%  net {x[\'net\']*100:+6.2f}%"\n                    f"  med {x[\'med\']*100:+6.2f}%  win {x[\'win\']*100:4.1f}%  net-SPY {x[\'xs_spy\']*100:+6.2f}% (t {x[\'t_xs\']:4.1f})")\n    return "\\n".join(rows)\n\n\ndef slot_sim(P, events, H, K, entry="close", fixed_side=None):\n    """Portfolio with K equal slots; takes events (t, j, score) best score first when a slot is free.\n    Exit at close t+H. Cash earns 0. Returns daily returns and #trades."""\n    c, o, spr, R = P["c"], P["o"], P["spr"], P["R"]\n    T = c.shape[0]\n    byt = {}\n    for t, j, sc in events:\n        byt.setdefault(t, []).append((sc, j))\n    cash, pos, pend = 1.0, {}, []    # pos: j -> [value, exit_day, first_mark_day]\n    eq_prev = 1.0; ret = np.zeros(T); ntr = 0\n    hs = lambda d, j: fixed_side if fixed_side is not None else (spr[d, j] if np.isfinite(spr[d, j]) else 0.01) / 2\n    for d in range(T):\n        for j, alloc in pend:                       # open entries decided at yesterday\'s close\n            if j not in pos and np.isfinite(o[d, j]) and np.isfinite(c[d, j]) and o[d, j] > 0:\n                side_o = fixed_side if fixed_side is not None else P["spr_o"][d, j] / 2\n                pos[j] = [alloc * (1 - side_o) * (c[d, j] / o[d, j]), d - 1 + H, d + 1]\n                ntr += 1\n            else:\n                cash += alloc\n        pend = []\n        for j, p in pos.items():\n            if d >= p[2]:\n                p[0] *= (1 + R[d, j])\n        for j in [j for j, p in pos.items() if p[1] <= d]:\n            cash += pos[j][0] * (1 - hs(d, j)); del pos[j]\n        eq = cash + sum(p[0] for p in pos.values())\n        free = K - len(pos)\n        if free > 0 and d in byt:\n            for sc, j in sorted(byt[d], reverse=True):\n                if free <= 0 or cash <= 1e-12:\n                    break\n                if j in pos or any(j == q for q, _ in pend) or not np.isfinite(c[d, j]) or d + H >= T:\n                    continue\n                alloc = min(eq / K, cash)\n                cash -= alloc\n                if entry == "close":\n                    pos[j] = [alloc * (1 - hs(d, j)), d + H, d + 1]; ntr += 1\n                else:\n                    pend.append((j, alloc))\n                free -= 1\n        eq = cash + sum(p[0] for p in pos.values()) + sum(a for _, a in pend)\n        ret[d] = eq / eq_prev - 1\n        eq_prev = eq\n    return ret, ntr\n', 'lh_run': '"""cands + analyze phases"""\nimport json, os, sys, random, collections\nimport numpy as np, pandas as pd\nimport lh_core as C\nimport lh_strat as S\nOUT = "/tmp/lh"\nLOG = []\nNCELLS = collections.Counter()\n\n\ndef say(*a):\n    s = " ".join(str(x) for x in a)\n    print(s, flush=True); LOG.append(s)\n\n\ndef month_ends(dates):\n    m = dates.to_period("M")\n    return np.where(np.r_[m[1:] != m[:-1], True])[0][:-1]      # exclude the (partial) last month\n\n\ndef week_ends(dates):\n    w = dates.to_period("W-FRI")\n    return np.where(np.r_[w[1:] != w[:-1], True])[0][:-1]\n\n\ndef cands(P):\n    d, T = P["dates"], len(P["dates"])\n    c, o, v = P["c"], P["o"], P["v"]\n    el_prev = np.vstack([np.zeros((1, c.shape[1]), bool), P["elig"][:-1]])\n    cp = np.vstack([np.full((1, c.shape[1]), np.nan), c[:-1]])\n    with np.errstate(all="ignore"):\n        gap = o / cp - 1; cc = c / cp - 1; rv = v / P["vavg20_prev"]\n    m = el_prev & (rv >= 2) & ((gap >= 0.05) | (cc >= 0.10))\n    tt, jj = np.where(m)\n    out = {}\n    for t, j in zip(tt, jj):\n        k = str(d[t].date())\n        out.setdefault(k, {"prev": str(d[t - 1].date()), "syms": []})["syms"].append(str(P["syms"][j]))\n    json.dump(out, open(f"{OUT}/news_cands.json", "w"))\n    say("news candidate name-days", len(tt), "days", len(out))\n    # quote sample: 25 random days 2025-01..2026-09, per day 4 liquid + 4 (5-50M) + 4 band names\n    rng = random.Random(7)\n    idx = [t for t in range(T) if d[t] >= pd.Timestamp("2025-01-02")]\n    smp = {}\n    for t in rng.sample(idx, 25):\n        pools = [np.where(P["liquid"][t])[0], np.where(P["elig"][t] & ~P["liquid"][t])[0], np.where(P["band"][t])[0]]\n        ss = set()\n        for pl in pools:\n            ss |= set(P["syms"][rng.sample(list(pl), min(4, len(pl)))].tolist())\n        smp[str(d[t].date())] = sorted(ss)\n    json.dump(smp, open(f"{OUT}/quote_sample.json", "w"))\n    say("quote sample name-days", sum(len(v) for v in smp.values()))\n\n\ndef spread_check(P):\n    p = f"{OUT}/quotes.json"\n    if not os.path.exists(p):\n        say("no quotes.json"); return\n    q = json.load(open(p))\n    col = {s: j for j, s in enumerate(P["syms"])}\n    dix = {str(x.date()): i for i, x in enumerate(P["dates"])}\n    rows = []\n    for key, m in q.items():\n        d, hm = key.split()\n        t = dix[d]\n        for s, sp in m.items():\n            j = col.get(s)\n            if j is None:\n                continue\n            rows.append(dict(d=d, hm=hm, s=s, q=sp, ar=P["spr_ar"][t, j], cs=P["spr_cs"][t, j], est=P["spr_arm"][t, j],\n                             qm=(P["spr_o"][t, j] if hm == "09:35" else P["spr"][t, j]),\n                             liq=bool(P["liquid"][t, j]), band=bool(P["band"][t, j]), px=P["rc"][t, j], adv=P["adv20"][t, j]))\n    df = pd.DataFrame(rows)\n    say("\\n## Spread estimator vs real SIP quotes (sample; values in bp of mid, medians)")\n    for nm, g in (("liquid >=$50M", df[df.liq]), ("$5-50M", df[~df.liq]), ("$20-100 band", df[df.band])):\n        piv = g.groupby("hm").q.median() * 1e4\n        nm_n = g[["d", "s"]].drop_duplicates().shape[0]\n        est = g.drop_duplicates(["d", "s"])\n        say(f"{nm:14s} name-days={nm_n:3d}  quoted 09:35 {piv.get(\'09:35\', np.nan):6.1f}  12:30 {piv.get(\'12:30\', np.nan):6.1f}  15:55 {piv.get(\'15:55\', np.nan):6.1f}"\n            f" | AR {est.ar.median()*1e4:6.1f}  CS {est.cs.median()*1e4:6.1f}  model(AR floored at 1 tick) {est.est.median()*1e4:6.1f}"\n            f" | mean quoted {g.q.mean()*1e4:6.1f} vs mean AR-model {est.est.mean()*1e4:6.1f}; quote-model (in-sample) mean {g.qm.mean()*1e4:6.1f}")\n    x = df.groupby(["d", "s"]).agg(q=("q", "mean"), est=("est", "first"), ar=("ar", "first"), cs=("cs", "first")).dropna()\n    say(f"name-level rank corr with quoted (mean of the 3 times): AR-model {x[[\'q\',\'est\']].corr(method=\'spearman\').iloc[0,1]:.2f}, raw AR {x[[\'q\',\'ar\']].corr(method=\'spearman\').iloc[0,1]:.2f}, CS {x[[\'q\',\'cs\']].corr(method=\'spearman\').iloc[0,1]:.2f}")\n    y = df.dropna(subset=["q", "qm"])\n    say(f"quote-model vs quoted, rank corr {y[[\'q\',\'qm\']].corr(method=\'spearman\').iloc[0,1]:.2f} (in-sample fit on these same quotes)")\n    return df\n\n\ndef mom_signal(P, t):\n    cf, c = P["cf"], P["c"]\n    if t < 252:\n        return None\n    with np.errstate(all="ignore"):\n        s = cf[t - 21] / cf[t - 252] - 1\n    nv = np.isfinite(c[t - 252:t + 1]).sum(0)\n    ok = np.isfinite(s) & np.isfinite(c[t - 252]) & (nv >= 200)\n    return np.where(ok, s, np.nan)\n\n\ndef pick_top(sig, msk, how):\n    x = np.where(msk & np.isfinite(sig), sig, np.nan)\n    ok = np.where(np.isfinite(x))[0]\n    if len(ok) < 30:\n        return np.array([], int)\n    order = ok[np.argsort(-x[ok])]\n    n = {"dec": max(len(ok) // 10, 1), "top20": 20, "top10": 10}[how]\n    return order[:n]\n\n\ndef report_series(name, ret, P, turn=None, cost=None, extra=""):\n    NCELLS[name.split(":")[0]] += 1\n    m = C.metrics(ret, P["dates"], P["spy_r"])\n    say(f"\\n### {name} {extra}")\n    say(C.fmt_m(m))\n    say("  by year (strategy vs SPY %):", C.fmt_years(m))\n    if turn is not None:\n        yrs = len(P["dates"]) / 252\n        say(f"  one-way turnover {sum(turn)/yrs*100:.0f}%/yr; mean cost drag {np.sum(cost)/yrs*100:.2f}%/yr")\n    return m\n\n\ndef analyze(P):\n    P = S.returns(P)\n    d = P["dates"]; T = len(d)\n    say("# LONGER HOLDS study raw output")\n    say("panel", d[0].date(), "->", d[-1].date(), "T", T, "N", len(P["syms"]), "inactive", int((P["status"] == "inactive").sum()))\n    ne = P["elig"].sum(1)\n    say("eligible names/day (median by year):", {int(y): int(np.median(ne[d.year == y])) for y in sorted(set(d.year))})\n    say("liquid names/day (median):", int(np.median(P["liquid"].sum(1)[260:])), " band:", int(np.median(P["band"].sum(1)[260:])))\n    # delisted coverage\n    lastd = pd.Series([d[np.where(np.isfinite(P["c"][:, j]))[0][-1]].year if np.isfinite(P["c"][:, j]).any() else 0\n                       for j in range(len(P["syms"]))])\n    say("series ending before 2026-09 by year (delisted/renamed coverage):", lastd[lastd < 2026].value_counts().sort_index().to_dict())\n    spread_check(P)\n    say("\\nPRIMARY cost model = quote-calibrated (AR/CS fail the name-level cross-check above). fits:", json.dumps(P["qfit"]))\n    for key, nm in (("spr", "15:55 (close trades)"), ("spr_o", "09:35 (open trades)"), ("spr_arm", "AR model (reference)")):\n        say(f"  full spread {nm}: mean bp over eligible name-days by year",\n            {int(y): round(float(np.nanmean(P[key][d.year == y][P["elig"][d.year == y]])) * 1e4, 1) for y in sorted(set(d.year))},\n            "| liquid", round(float(np.nanmean(P[key][P["liquid"]])) * 1e4, 1), " band", round(float(np.nanmean(P[key][P["band"]])) * 1e4, 1))\n\n    spy_bh = P["spy_r"].copy(); spy_bh[:252] = 0\n    res = {}\n    # ---------------- 1. momentum 12-1\n    say("\\n## 1. Cross-sectional 12-1 momentum, monthly rebalance at month-end close, equal weight (costs = half model spread per traded $)")\n    me = [t for t in month_ends(d) if t >= 252]\n    for uni in ("elig", "liquid", "band"):\n        msk = P[uni]\n        ew_p = [np.where(msk[t] & np.isfinite(P["c"][t]))[0] for t in me]\n        r, cs, tn = S.rebal_portfolio(P, me, ew_p, "close")\n        res[f"ew_{uni}"] = report_series(f"benchmark:EW universe [{uni}]", r, P, tn, cs)\n        sigs = {t: mom_signal(P, t) for t in me}\n        for how in ("dec", "top20", "top10"):\n            pk = [pick_top(sigs[t], msk[t], how) for t in me]\n            r, cs, tn = S.rebal_portfolio(P, me, pk, "close")\n            res[f"mom_{uni}_{how}"] = report_series(f"momentum:{uni} {how}", r, P, tn, cs,\n                                                    f"(avg names {np.mean([len(x) for x in pk]):.0f})")\n            if how == "top20":\n                r0, _, _ = S.rebal_portfolio(P, me, pk, "close", fixed_side=0.0)\n                m0 = C.metrics(r0, d, P["spy_r"])\n                say(f"  gross (no cost) OOS CAGR {m0[\'OOS\'][\'cagr\']*100:.1f}%  Sharpe {m0[\'OOS\'][\'sharpe\']:.2f}; IS CAGR {m0[\'IS\'][\'cagr\']*100:.1f}%")\n    say("\\n### SPY buy-and-hold (from 2017-01 like the strategies)")\n    say(C.fmt_m(C.metrics(spy_bh, d, P["spy_r"])))\n    # ---------------- 2. short-term reversal\n    say("\\n## 2. Short-term reversal: buy the 1-week losers at Friday close signal, enter next open, hold one week (industry-neutral: no sector data -> not run)")\n    we = [t for t in week_ends(d) if t >= 252 and t + 1 < T]\n    for uni in ("elig", "liquid", "band"):\n        msk = P[uni]\n        for how in ("dec", "top20"):\n            pk = []\n            for t in we:\n                with np.errstate(all="ignore"):\n                    s = -(P["cf"][t] / P["cf"][t - 5] - 1)\n                s = np.where(np.isfinite(P["c"][t - 5]), s, np.nan)\n                pk.append(pick_top(s, msk[t], how))\n            r, cs, tn = S.rebal_portfolio(P, we, pk, "open")\n            res[f"rev_{uni}_{how}"] = report_series(f"reversal:{uni} {how}", r, P, tn, cs)\n            r0, _, _ = S.rebal_portfolio(P, we, pk, "open", fixed_side=0.0)\n            m0 = C.metrics(r0, d, P["spy_r"])\n            say(f"  gross (no cost) OOS CAGR {m0[\'OOS\'][\'cagr\']*100:.1f}%  IS CAGR {m0[\'IS\'][\'cagr\']*100:.1f}%")\n    # ---------------- 4. overnight\n    say("\\n## 4. Overnight: buy the close, sell the next open, every session (cost A = half the modelled 15:55 quoted spread in + half the modelled 09:35 spread out; cost B = 2 bp/side auction (MOC/MOO) assumption)")\n    ON, ID = P["ON"], P["ID"]\n    cc1 = np.full_like(P["c"], np.nan); cc1[1:] = P["c"][1:] / P["c"][:-1] - 1\n    momd = np.full_like(P["c"], np.nan)\n    with np.errstate(all="ignore"):\n        momd[252:] = P["cf"][231:-21] / P["cf"][:-252] - 1\n    sets = {}\n    for uni in ("elig", "liquid", "band"):\n        sets[f"EW {uni}"] = lambda t, u=uni: np.where(P[u][t])[0]\n    sets["top20 day gainers (elig)"] = lambda t: pick_top(cc1[t], P["elig"][t], "top20")\n    sets["top20 day gainers (liquid)"] = lambda t: pick_top(cc1[t], P["liquid"][t], "top20")\n    sets["top20 12-1 momentum (liquid)"] = lambda t: pick_top(momd[t], P["liquid"][t], "top20")\n    for nm, fn in sets.items():\n        gA = np.zeros(T); nA = np.zeros(T); nB = np.zeros(T); gI = np.zeros(T)\n        for t in range(252, T - 1):\n            j = fn(t)\n            if len(j) == 0:\n                continue\n            on = ON[t + 1, j]; ok = np.isfinite(on)\n            if ok.sum() == 0:\n                continue\n            g = on[ok].mean(); cst = (P["spr"][t, j][ok] / 2 + P["spr_o"][t + 1, j][ok] / 2).mean()\n            gA[t + 1] = g; nA[t + 1] = (1 + g) * (1 - cst) - 1; nB[t + 1] = (1 + g) * (1 - 0.0002) ** 2 - 1\n            idr = ID[t + 1, j]; gI[t + 1] = np.nanmean(idr) if np.isfinite(idr).any() else 0\n        yrs = (T - 253) / 252\n        mg = C.metrics(gA, d, P["spy_r"])\n        say(f"\\n### overnight:{nm}  gross mean {gA[253:].mean()*1e4:.1f} bp/night (IS {gA[253:][d[253:] <= C.IS_END].mean()*1e4:.1f}, OOS {gA[253:][d[253:] > C.IS_END].mean()*1e4:.1f});"\n            f" same names next-day intraday leg {gI[253:].mean()*1e4:.1f} bp; round-trip model cost {np.mean((gA-nA)[253:])*1e4:.1f} bp")\n        say("  gross:", C.fmt_m(mg).replace("\\n", "\\n         "))\n        res[f"on_{nm}_A"] = report_series(f"overnight:{nm} cost A", nA, P)\n        res[f"on_{nm}_B"] = report_series(f"overnight:{nm} cost B", nB, P)\n    spy_on = P["spy_on"].copy(); spy_on[:253] = 0\n    say(f"\\n### SPY overnight only: mean {spy_on[253:].mean()*1e4:.2f} bp/night")\n    say(C.fmt_m(C.metrics(spy_on, d, P["spy_r"])))\n    nB = (1 + spy_on) * (1 - 0.0001) ** 2 - 1; nB[:253] = 0\n    say("  SPY overnight net 1 bp/side:\\n" + C.fmt_m(C.metrics(nB, d, P["spy_r"])))\n    NCELLS["overnight"] += 1\n    say("\\n## Cost sensitivity + variants for the cells that are positive gross (fixed cost per side, bp)")\n    for nm, K, uni in (("top10 12-1 momentum (liquid)", 10, "liquid"), ("top20 12-1 momentum (liquid)", 20, "liquid"),\n                       ("top50 12-1 momentum (liquid)", 50, "liquid"), ("top20 12-1 momentum (band)", 20, "band"),\n                       ("top20 12-1 momentum (elig)", 20, "elig")):\n        g = np.zeros(T)\n        for t in range(252, T - 1):\n            x = np.where(P[uni][t] & np.isfinite(momd[t]), momd[t], np.nan)\n            ok = np.where(np.isfinite(x))[0]\n            if len(ok) < 30:\n                continue\n            j = ok[np.argsort(-x[ok])][:K]\n            on = ON[t + 1, j]\n            if np.isfinite(on).any():\n                g[t + 1] = np.nanmean(on)\n        NCELLS["overnight"] += 1\n        row = []\n        for bp in (0, 2, 5, 10):\n            n_ = (1 + g) * (1 - bp / 1e4) ** 2 - 1; n_[:253] = 0\n            m = C.metrics(n_, d, P["spy_r"])\n            row.append(f"{bp}bp/side: OOS CAGR {m[\'OOS\'][\'cagr\']*100:+.1f}% Sh {m[\'OOS\'][\'sharpe\']:.2f} a {m[\'OOS\'][\'alpha\']*100:+.1f}% (t {m[\'OOS\'][\'alpha_t\']:.1f}); IS CAGR {m[\'IS\'][\'cagr\']*100:+.1f}%")\n        say(f"overnight:{nm}  gross {g[253:].mean()*1e4:.1f} bp/night (OOS {g[253:][d[253:] > C.IS_END].mean()*1e4:.1f})\\n   " + "\\n   ".join(row))\n        if K == 20 and uni == "liquid":\n            n_ = (1 + g) * (1 - 2 / 1e4) ** 2 - 1; n_[:253] = 0\n            m = C.metrics(n_, d, P["spy_r"])\n            say("   by year @2bp/side:", C.fmt_years(m))\n            # half-sample / concentration check: drop the best 1% of nights\n            gg = g[253:].copy(); thr = np.quantile(gg, 0.99)\n            say(f"   mean without the best 1% nights: {gg[gg < thr].mean()*1e4:.1f} bp; share of nights > 0: {(gg > 0).mean()*100:.1f}%")\n    for nm, key in (("momentum:liquid dec", ("liquid", "dec")), ("momentum:liquid top20", ("liquid", "top20"))):\n        pass\n    # ---------------- 3 & 5 events\n    news = json.load(open(f"{OUT}/news.json")) if os.path.exists(f"{OUT}/news.json") else {}\n    say(f"\\nnews days loaded: {len(news)}")\n    c, o, v = P["c"], P["o"], P["v"]\n    cp = np.vstack([np.full((1, c.shape[1]), np.nan), c[:-1]])\n    el_prev = np.vstack([np.zeros((1, c.shape[1]), bool), P["elig"][:-1]])\n    with np.errstate(all="ignore"):\n        gap = o / cp - 1; cc = c / cp - 1; rv = v / P["vavg20_prev"]\n\n    def nflag(t, j, kind):\n        x = news.get(str(d[t].date()), {}).get(str(P["syms"][j]))\n        if kind == "any":\n            return True\n        if x is None:\n            return False\n        return x["earn"] > 0 if kind == "earn" else x["n"] > 0\n\n    say("\\n## 3. Post-earnings / gap drift: open gap >= X on RVOL >= 2 (full-day volume / prior 20d avg), price>=$5 & ADV>=$5M the day before")\n    for X in (0.05, 0.10):\n        tt, jj = np.where(el_prev & (gap >= X) & (rv >= 2))\n        tt, jj = tt[tt >= 252], jj[tt >= 252]\n        for kind in ("earn", "any"):\n            ev = [(int(t), int(j), float(gap[t, j])) for t, j in zip(tt, jj) if nflag(t, j, kind)]\n            say(f"\\n-- gap>={int(X*100)}% flag={kind}: {len(ev)} events")\n            for entry in ("close", "open"):\n                for H in (5, 20, 60):\n                    tr = S.event_trades(P, ev, H, entry)\n                    sm = S.trade_summary(tr, d)\n                    NCELLS["pead"] += 1\n                    say(f"#### pead gap>={int(X*100)}% {kind} entry={entry} hold={H}d (per trade, first event per name per hold window)")\n                    say(S.fmt_t(sm))\n                    say("   by year n/net/net-SPY %: " + "  ".join(f"{y}:{n}/{a*100:+.1f}/{b*100:+.1f}" for y, (n, a, b) in sm["years"].items()))\n                    if entry == "open" or kind == "earn":\n                        K = 10 if H <= 20 else 20\n                        r, ntr = S.slot_sim(P, ev, H, K, entry)\n                        res[f"pead_{X}_{kind}_{entry}_{H}"] = report_series(f"pead:slot portfolio K={K} gap>={int(X*100)}% {kind} {entry} H={H}", r, P,\n                                                                             extra=f"({ntr} trades, {ntr/((T-252)/252):.0f}/yr)")\n    say("\\n## 5. Daily gap-and-go continuation: close-to-close >= +10% on RVOL >= 3, buy that close, hold 1/5/20 sessions")\n    for band_nm, bm in (("price>=$5", np.ones_like(c, bool)), ("$5-20", (P["rc"] < 20)), ("$20-100", (P["rc"] >= 20) & (P["rc"] <= 100))):\n        tt, jj = np.where(el_prev & (cc >= 0.10) & (rv >= 3) & bm & (P["rc"] >= 5))\n        tt, jj = tt[tt >= 252], jj[tt >= 252]\n        for kind in ("news", "any"):\n            ev = [(int(t), int(j), float(rv[t, j])) for t, j in zip(tt, jj) if nflag(t, j, kind)]\n            say(f"\\n-- {band_nm} up>=10% rvol>=3 flag={kind}: {len(ev)} events")\n            for H in (1, 5, 20):\n                tr = S.event_trades(P, ev, H, "close")\n                sm = S.trade_summary(tr, d)\n                NCELLS["gapgo"] += 1\n                say(f"#### gapgo {band_nm} {kind} hold={H}d")\n                say(S.fmt_t(sm))\n                say("   by year n/net/net-SPY %: " + "  ".join(f"{y}:{n}/{a*100:+.1f}/{b*100:+.1f}" for y, (n, a, b) in sm["years"].items()))\n                if band_nm == "price>=$5":\n                    r, ntr = S.slot_sim(P, ev, H, 10, "close")\n                    res[f"gg_{kind}_{H}"] = report_series(f"gapgo:slot portfolio K=10 {kind} H={H}", r, P, extra=f"({ntr} trades)")\n    say("\\n## multiple-testing tally (cells evaluated):", dict(NCELLS), "total", sum(NCELLS.values()))\n    open(f"{OUT}/LONGER_HOLDS_raw.txt", "w").write("\\n".join(LOG) + "\\n")\n    json.dump(res, open(f"{OUT}/results.json", "w"), default=float, indent=0)\n\n\nif __name__ == "__main__":\n    P = C.load()\n    {"cands": cands, "analyze": analyze, "spread": spread_check}[sys.argv[1]](P)\n'}


def unpack(dst="/tmp/lh"):
    os.makedirs(dst, exist_ok=True)
    for m, s in MODULES.items():
        p = os.path.join(dst, m + ".py")
        open(p, "w").write(s)
        print("wrote", p)


if __name__ == "__main__":
    if sys.argv[1:2] == ["unpack"]:
        unpack(*sys.argv[2:3])
    else:
        print(__doc__)
